import{_ as t,o as e,c as r,aa as a}from"./chunks/framework.BAs_AphD.js";const n="/buildary-help-preview/academy/img/nacteni-rozpoctu/02.webp",p="/buildary-help-preview/academy/img/nacteni-rozpoctu/06.webp",k=JSON.parse('{"title":"Načíst rozpočet","description":"","frontmatter":{"title":"Načíst rozpočet","wiki":"cs:performedworks:budget"},"headers":[],"relativePath":"performedworks/budget.md","filePath":"performedworks/budget.md","lastUpdated":1794209661000}'),s={name:"performedworks/budget.md"};function i(d,o,u,l,m,v){return e(),r("div",null,[...o[0]||(o[0]=[a('<h1 id="nacist-rozpocet" tabindex="-1">Načíst rozpočet <a class="header-anchor" href="#nacist-rozpocet" aria-label="Permalink to &quot;Načíst rozpočet&quot;">​</a></h1><p>Soupisy provedených prací se zadávají k položkám rozpočtu, proto musí být na stavbě nejdřív načtený rozpočet. Rozpočet se v průběhu stavby mění, a tak ho můžete načítat opakovaně – vždy ze stejného zdroje.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/nacteni-rozpoctu">Nahrát rozpočet z Excelu</a> v Akademii.</p><p>Dokud rozpočet načtený není, okno soupisu žádné položky nezobrazí a místo nich ukáže hlášení <strong>Nelze zobrazit žádné položky rozpočtu</strong> – viz <a href="/buildary-help-preview/performedworks/competences#kdyz-okno-soupisu-nic-neukazuje">Kompetence pro soupisy</a>.</p><h2 id="odkud-rozpocet-nacist" tabindex="-1">Odkud rozpočet načíst <a class="header-anchor" href="#odkud-rozpocet-nacist" aria-label="Permalink to &quot;Odkud rozpočet načíst&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Zdroj</th><th>Jak se rozpočet načte</th></tr></thead><tbody><tr><td><strong>RSV – Řízení stavební výroby</strong></td><td>Informační systém pro stavební firmy od společnosti First information systems. Je s Buildary přímo propojený: stavbu založíte a rozpočet přenesete tlačítky přímo v RSV.</td></tr><tr><td><strong>Excel</strong></td><td>Rozpočet upravíte do tvaru šablony Buildary a šablonu naimportujete v okně soupisu – viz <a href="#import-z-excelu">Import z Excelu</a>.</td></tr><tr><td><strong>KROS 4</strong></td><td>Import je možný z KROS 4 ve verzi 2024 a vyšší.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Na jedné stavbě jen jeden zdroj</p><p>Zdroje rozpočtu nelze na jedné stavbě kombinovat. Když rozpočet poprvé načtete z Excelu a pak zkusíte import z KROS 4, nová data původní rozpočet přepíšou. Zvolte jeden zdroj a ten používejte po celou dobu stavby.</p></div><h2 id="import-z-excelu" tabindex="-1">Import z Excelu <a class="header-anchor" href="#import-z-excelu" aria-label="Permalink to &quot;Import z Excelu&quot;">​</a></h2><p>V okně <strong>SPP Zhotovitele</strong> otevřete menu <strong>⋮</strong> vedle tlačítek pro změnu stavu zjišťovacího protokolu.</p><figure class="shot" style="--w:760px;"><img src="'+n+'" alt="Menu vedle tlačítka Odeslat na schválení s volbami Import rozpočtu a Stažení šablony" loading="lazy"></figure><table tabindex="0"><thead><tr><th>Volba</th><th>K čemu slouží</th></tr></thead><tbody><tr><td><strong>Stažení šablony</strong></td><td>Stáhne vzorový soubor Excel s popisem formátu. Do něj rozpočet převedete.</td></tr><tr><td><strong>Import rozpočtu</strong></td><td>Otevře okno <strong>Import rozpočtu</strong>. Soubor vyberte tlačítkem <strong>Procházet</strong> nebo ho do okna přetáhněte a klikněte na <strong>Importovat rozpočet</strong>.</td></tr></tbody></table><p>Po importu okno ukáže <strong>Výsledek importu</strong>: název souboru a stav, například <strong>Import proběhl s upozorněními</strong> s počtem upozornění. Podrobný výsledek si stáhnete ikonou na konci řádku. V části <strong>Historie nahraných souborů</strong> je každý dříve nahraný soubor s datem, časem a jménem toho, kdo ho nahrál, a i ten si můžete stáhnout.</p><figure class="shot" style="--w:760px;"><img src="'+p+'" alt="Okno Import rozpočtu s výsledkem importu a historií nahraných souborů" loading="lazy"></figure><p>Načtený rozpočet se zobrazí v okně soupisu se všemi objekty, díly a položkami.</p><h2 id="opakovany-import" tabindex="-1">Opakovaný import <a class="header-anchor" href="#opakovany-import" aria-label="Permalink to &quot;Opakovaný import&quot;">​</a></h2><p>Okno importu upozorňuje, že importem šablony se původní rozpočet nahradí novými daty ze šablony. Položky se přitom párují podle <strong>ID záznamu</strong>. Když položka má stejné ID jako při prvním importu, zůstanou k ní navázané i soupisy, které jste k ní už zadali.</p><ul><li>Importovaný soubor si uschovejte. Při každé změně rozpočtu – nové položky, jiné množství, smazané položky – upravte vždy tento soubor a naimportujte ho znovu.</li><li>ID záznamu u položek po prvním importu neměňte. S jinými ID se položky nespárují a importem si data rozbijete.</li><li>U KROS 4 importujte vždy ze stejné stavby, ze které jste rozpočet načetli poprvé. Změny dělejte v této původní stavbě. Import z jiné stavby, třeba z její kopie, data rozbije.</li></ul><h2 id="firmy-a-podzhotovitele-v-rozpoctu" tabindex="-1">Firmy a podzhotovitelé v rozpočtu <a class="header-anchor" href="#firmy-a-podzhotovitele-v-rozpoctu" aria-label="Permalink to &quot;Firmy a podzhotovitelé v rozpočtu&quot;">​</a></h2><p>Rozpočet určuje i to, kdo položky vidí. Firmy uvedené v rozpočtu se nabízejí v záhlaví okna soupisu (<strong>Stavebník</strong>, <strong>Zhotovitel</strong>, <strong>Podzhotovitel</strong>). Pokud firma, ke které je uživatel přiřazen v projektovém týmu, není u žádné položky rozpočtu, uživatel v okně soupisu žádné položky neuvidí – viz <a href="/buildary-help-preview/performedworks/competences">Kompetence pro soupisy</a>.</p><p>Položky, které mají v rozpočtu vyplněnou kalkulační část s podzhotovitelem, se objeví v okně <strong>SPP Podzhotovitele</strong>. Tam o nich vede soupis podzhotovitel se zhotovitelem – viz <a href="/buildary-help-preview/performedworks/">Soupisy provedených prací</a>.</p>',20)])])}const h=t(s,[["render",i]]);export{k as __pageData,h as default};
